import {programmeName} from './programme-names.mjs';
import {campusPhotos,photoRecords} from './campus-photos.mjs';
import {comparisonTests,nearestDeadline} from './comparison.mjs';
import {interests,interestDescription,catalogueSummary} from './interests.mjs';
import {countryMatches,destinationOptions} from './destinations.mjs';
import {subjectMatches} from './subjects.mjs';
import {translateText,localizeDOM,searchAliases} from './localize.mjs';
import {translations} from './i18n.mjs';
import {regions,coverageLabels,testLabels,money,enrich,filterRoutes,deadlineState,addComparison,safeStored,safeSave} from './logic.mjs';
const $=s=>document.querySelector(s);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let storage;try{storage=window.localStorage;}catch{storage={getItem:()=>null,setItem:()=>{throw Error('Unavailable');}};}
const prefs=safeStored(storage,'divergents.preferences',{});
let lang=['en','kk','ru'].includes(prefs.lang)?prefs.lang:'en',year=+prefs.year||2027;
let saved=safeStored(storage,'divergents.shortlist',[]),compare=safeStored(storage,'divergents.compare',[]),page='explore',selected=null,onlySaved=false;
let f={fields:[],year,costUnknown:true,testUnknown:false};
let visibleLimit=6;
const d=await fetch('./catalogue.json').then(r=>{if(!r.ok)throw Error('Catalogue unavailable');return r.json();}).catch(e=>{$('#main').innerHTML='<div class="empty">The catalogue could not load. Please reload this page.</div>';localizeDOM($('#main'),lang);throw e;});
const routes=enrich(d);saved=Array.isArray(saved)?saved.filter(id=>routes.some(r=>r.id===id)):[];compare=Array.isArray(compare)?compare.filter(id=>routes.some(r=>r.id===id)).slice(0,3):[];
const t=k=>translations[lang][k]||translations.en[k]||k;
function localize(root=document.body){localizeDOM(root,lang);}
const tr=value=>translateText(value,lang);
for(const r of routes)r.searchAliases=searchAliases(r);
function persist(){safeSave(storage,'divergents.preferences',{lang,year});}
function toast(message){$('#toast').textContent=tr(message);$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),3500);}
function storeList(){if(!safeSave(storage,'divergents.shortlist',saved)||!safeSave(storage,'divergents.compare',compare))toast('Browser storage unavailable. Changes will last for this visit only.');}
function btn(action,label,cls='',attrs=''){return `<button type="button" data-action="${action}" class="${cls}" ${attrs}>${label}</button>`;}
function options(values,current,any=t('all')){return `<option value="">${esc(any)}</option>`+values.map(v=>`<option value="${esc(v)}" ${v===current?'selected':''}>${esc(v)}</option>`).join('');}
function header(){document.documentElement.lang=lang;document.title=tr('Divergents · Find your next direction');document.querySelector('meta[name=description]').content=tr('Explore colleges and universities after Grade 9 or Grade 11 with Divergents. Search, save and compare your options.');$('.skip').textContent=tr('Skip to content');$('#header').innerHTML=`<div class="header-inner"><a class="brand" href="#" data-action="home"><span class="brandmark" aria-hidden="true">d.</span><span>Divergents</span></a><nav aria-label="Main navigation">${['explore','shortlist','compare'].map(p=>btn('page',`${t(p)}${p==='shortlist'&&saved.length?` <span class="count">${saved.length}</span>`:''}`,page===p?'active':'',`data-page="${p}" aria-current="${page===p?'page':'false'}"`)).join('')}</nav><label class="language"><span class="sr">Interface language</span><select id="lang"><option value="en" ${lang==='en'?'selected':''}>EN</option><option value="kk" ${lang==='kk'?'selected':''}>ҚАЗ</option><option value="ru" ${lang==='ru'?'selected':''}>РУС</option></select></label></div>`;}
function hero(){return `<section class="hero simple-hero"><div class="hero-content"><p class="hero-eyebrow">Universities and colleges</p><h1>Where would you like to study?</h1><p class="hero-subtitle">Start with a country or an interest.</p><div class="pathway-choices" role="group" aria-label="Choose an entry pathway">${btn('entry','After Grade 9','pathway-choice '+(f.stage==='9'?'selected':''),'data-stage="9" aria-pressed="'+(f.stage==='9')+'"')}${btn('entry','After Grade 11','pathway-choice '+(f.stage==='11'?'selected':''),'data-stage="11" aria-pressed="'+(f.stage==='11')+'"')}${btn('entry','All options','pathway-choice '+(!f.stage?'selected':''),'data-stage="" aria-pressed="'+(!f.stage)+'"')}</div></div></section>`;}
function selectFilter(id,label,vals,current){return `<label>${label}<select id="${id}" data-filter="${id}">${options(vals,current)}</select></label>`;}
function filters(){const selected=f.fields[0]||'';return `<aside class="filters" aria-label="${t('filters')}"><label>${t('country')}<select id="country" data-filter="country"><option value="">${t('all')}</option>${destinationOptions(lang).map(row=>`<option data-no-i18n value="${row.code}" ${f.country===row.code?'selected':''}>${esc(row.labels[lang])}</option>`).join('')}</select></label><label>What interests you?<select id="subject" data-filter="subject" aria-describedby="subject-help"><option value="">All interests</option>${interests.map(row=>`<option data-no-i18n value="${row.id}" ${selected===row.id?'selected':''}>${esc(row.labels[lang])}</option>`).join('')}</select><span id="subject-help" class="subject-help" data-no-i18n ${!selected?'hidden':''}>${esc(interestDescription(selected,lang))}</span></label>${btn('reset',t('reset'),'text-btn reset-simple')}</aside>`;}
function photoLicense(photo){return /^CC(?:0|[ -])/.test(photo.license)?photo.license:/public domain|^PD\b/i.test(photo.license)?tr('Public domain'):tr('Photo source');}
function campusImage(institution,variant='card'){const photo=campusPhotos[institution.id];if(!photo)return '';return `<figure class="campus-photo campus-photo--${variant}"><img data-campus-photo="${institution.id}" src="./${photo.src}" alt="${esc(photo.alt[lang])}" width="${photo.width}" height="${photo.height}" loading="lazy" decoding="async" style="object-position:${esc(photo.position||'50% 50%')}">${photo.needsContextCaption&&variant!=='detail'?`<span class="photo-context" data-no-i18n>${esc(photo.caption[lang])}</span>`:''}<span class="photo-fallback" hidden>${tr('Photo unavailable')}</span><figcaption class="photo-credit" data-no-i18n><a href="${esc(photo.sourcePage)}" target="_blank" rel="noopener noreferrer" aria-label="${esc(tr('Photo source'))}: ${esc(photo.caption[lang])}" title="${esc(photo.caption[lang])} · ${esc(photo.credit)} · ${esc(photoLicense(photo))}">${esc(photo.credit)} · ${esc(photoLicense(photo))}</a></figcaption></figure>${variant==='detail'?`<p class="campus-caption" data-no-i18n>${esc(photo.caption[lang])}</p>`:''}`;}
function photoCredits(){return `<details class="about-section photo-credits"><summary>Photo credits</summary><ul class="sources">${photoRecords.map(photo=>{const institution=d.institutions.find(i=>i.id===photo.institutionId);return `<li><strong>${esc(tr(institution.name))}</strong><p class="photo-caption" data-no-i18n>${esc(photo.caption[lang])}</p><span data-no-i18n>${esc(photo.credit)} · ${photo.licenseUrl?`<a href="${esc(photo.licenseUrl)}" target="_blank" rel="noopener noreferrer">${esc(photoLicense(photo))}</a>`:esc(photoLicense(photo))}</span> · <a href="${esc(photo.sourcePage)}" target="_blank" rel="noopener noreferrer">Photo source ↗</a></li>`;}).join('')}</ul></details>`;}
function routeCard(r){const multiple=routes.filter(x=>x.programmeId===r.programmeId&&x.entryAfter===r.entryAfter).length>1;return `<article class="route-card">${campusImage(r.i)}<div class="card-top"><span class="tag">${r.entryAfter===9?'After Grade 9':'After Grade 11'}</span>${btn('save',`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z"/></svg>`,'bookmark',`data-id="${r.id}" aria-label="${saved.includes(r.id)?t('remove'):t('save')} ${esc(programmeName(r.p,lang))} ${esc(r.name)}" aria-pressed="${saved.includes(r.id)}"`)}</div><p class="institution">${esc(r.i.name)}</p><h3>${esc(programmeName(r.p,lang))}</h3><p class="location">${esc(r.i.city)} · ${esc(r.i.country)}</p>${multiple?`<p class="route-name">${esc(r.name)}</p>`:''}<div class="simple-price"><small>Tuition reference</small><strong>${esc(money(r.tuition,lang))}</strong></div><div class="card-footer">${btn('detail','Details','primary',`data-id="${r.id}"`)}${btn('compare',`${compare.includes(r.id)?'✓ ':''}${t('compare')}`,'compare-btn',`data-id="${r.id}" aria-pressed="${compare.includes(r.id)}"`)}</div></article>`;}
function explorer(){return `${hero()}<div class="page-body explore-body"><section class="catalogue" id="catalogue"><div class="search-panel"><div class="search-wrap"><svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 4.5 4.5"/></svg><input type="search" id="search" value="${esc(f.q)}" placeholder="${t('search')}" aria-label="${t('search')}"></div>${filters()}</div><div class="catalogue-layout"><div><div class="result-bar"><strong id="resultCount" role="status" aria-live="polite"></strong></div><div class="active-filters" id="activeFilters"></div><div id="results" class="results"></div><div id="pagination" class="pagination"></div></div></div></section></div>`;}
function renderResults({reset=false}={}){if(reset)visibleLimit=6;const list=filterRoutes(routes,{...f,year});$('#resultCount').textContent=catalogueSummary(list,lang);$('#activeFilters').innerHTML=f.region?`<span>${esc(f.region)}</span>`:'';const regionEmpty=f.region&&!routes.some(r=>r.i.region===f.region);const countryGap=f.country&&!routes.some(r=>countryMatches(r.i.country,f.country));const subjectGap=f.fields.length&&!routes.some(r=>f.fields.some(field=>subjectMatches(r.p,field)));$('#results').innerHTML=list.length?list.slice(0,visibleLimit).map(routeCard).join(''):`<div class="empty"><h3>${countryGap?'No verified programmes for this destination yet':subjectGap?'No verified programmes in this subject yet':regionEmpty?'Verified coverage is still growing here':t('empty')}</h3><p>${countryGap||subjectGap||regionEmpty?'We are still adding verified options here.':'Try another country, interest or search.'}</p>${btn('reset',t('reset'),'primary')}${btn('page',t('coverage'),'text-btn','data-page="coverage"')}</div>`;$('#pagination').innerHTML=list.length>visibleLimit?btn('more','Show more','secondary','aria-controls="results"'):'';if($('#subject-help')){$('#subject-help').textContent=interestDescription(f.fields[0],lang);$('#subject-help').hidden=!f.fields.length;}for(const id of ['results','resultCount','activeFilters','pagination'])localize($('#'+id));}
function pageTitle(k,sub){return `<div class="page-title"><h1>${t(k)}</h1><p>${sub}</p></div>`;}
function shortlistPage(){return `<div class="page-body">${pageTitle('shortlist',t('local'))}<div class="results wide">${saved.length?saved.map(id=>routeCard(routes.find(r=>r.id===id))).join(''):`<div class="empty"><h2>A little curiosity goes a long way.</h2><p>Save any applicant route with the heart button. Come back here to compare your next steps.</p>${btn('page',t('explore'),'primary','data-page="explore"')}</div>`}</div></div>`;}
function deadlineHtml(x){const state=deadlineState(x,year);return `<article class="deadline"><span class="tag ${state==='Confirmed for selected cycle'?'green':''}">${esc(x.type)} · ${esc(state)}</span><h4>${esc(x.label)}</h4><strong>${x.date?esc(x.date):'Date awaiting publication'} ${x.time?esc(x.time):''} ${x.timezone?`· ${esc(x.timezone)}`:'· timezone not published'}</strong><p><b>${t('next')}:</b> ${esc(x.nextAction)}</p><details class="deadline-evidence"><summary>Applicant and official sources</summary><p>Cycle: ${esc(x.cycle)} · ${esc(x.applicant)}</p>${sourceList(x.sourceIds)}</details></article>`;}
function calendarPage(){const ds=d.deadlines.filter(x=>!onlySaved||x.routeIds.some(id=>saved.includes(id))).sort((a,b)=>(a.date||'9999').localeCompare(b.date||'9999'));const current=ds.filter(x=>deadlineState(x,year)==='Confirmed for selected cycle');const other=ds.filter(x=>!current.includes(x));const pending=routes.filter(r=>(!onlySaved||saved.includes(r.id))&&!r.deadlines.some(x=>String(x.cycle).startsWith(String(year))&&x.status!=='historical'));return `<div class="page-body narrow">${pageTitle('calendar','Keep track of your next steps.')}<div class="calendar-controls"><label>${t('year')}<input type="number" id="year" min="2026" max="2040" value="${year}"></label><label class="check"><input type="checkbox" id="onlySaved" ${onlySaved?'checked':''}> Shortlisted routes only</label></div>${current.length?current.map(deadlineHtml).join(''):`<div class="empty"><h3>Dates to confirm</h3><p>${year} cycle dates await confirmation.</p></div>`}<details class="pending-routes"><summary>Dates to confirm (${pending.length})</summary>${pending.map(r=>`<p>${btn('detail',`${esc(r.i.name)} · ${esc(programmeName(r.p,lang))}`,'text-btn',`data-id="${r.id}"`)}<small>${esc(r.nextAction)}</small></p>`).join('')}</details>${other.length?`<details class="pending-routes historical-dates"><summary>Other cycles and unpublished dates (${other.length})</summary>${other.map(deadlineHtml).join('')}</details>`:''}</div>`;}
function sourceList(ids){return `<ul class="sources">${[...new Set(ids||[])].map(id=>{const s=d.sources.find(s=>s.id===id);return s?`<li><a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.title)} ↗</a><small>${t('checked')} ${esc(s.checked)} · ${esc(s.cycle)} · ${esc(s.status)}<br>${esc(s.applicant)}${s.note?`<br>${esc(s.note)}`:''}</small></li>`:'';}).join('')}</ul>`;}
function testsHtml(r){return `<dl class="tests">${Object.entries(r.tests).map(([key,value])=>`<div><dt>${key==='UNT'?'ЕНТ / ҰБТ / UNT':key==='ENGLISH'?'English evidence':key==='PSYCHOMETRIC'?'Psychometric assessment':key==='PEDAGOGICAL'?'Teaching aptitude assessment':esc(key)}<span class="status ${value.status}">${testLabels[value.status]||'Awaiting verification'}</span></dt><dd>${esc(value.detail)}</dd></div>`).join('')}</dl>`;}
function awardsHtml(r){return r.awards.length?r.awards.map(a=>`<article class="award"><span class="tag green">${esc(coverageLabels[a.coverage])}</span><h4>${esc(a.name)}</h4><p>${esc(a.benefits)}</p><dl><dt>Who may apply</dt><dd>${esc(a.eligibility)}</dd><dt>Separate steps</dt><dd>${esc(a.application)}</dd><dt>Renewal</dt><dd>${esc(a.renewal)}</dd><dt>Upfront / remaining expenses</dt><dd>${esc(a.upfront)}</dd></dl><small>Award cycle: ${esc(a.cycle)} · Selection is competitive; eligibility thresholds are not acceptance odds.</small>${sourceList(a.sourceIds)}</article>`).join(''):`<p>${t('noAwards')}. Funding is unknown, rather than assumed unavailable or guaranteed.</p>`;}
function openDetail(id){const r=routes.find(r=>r.id===id);if(!r)return;selected=id;$('#detail').innerHTML=`<div class="detail-head"><span class="eyebrow">${esc(r.i.country)}</span>${btn('close',`${t('close')} ×`,'text-btn')}</div><div class="detail-body">${campusImage(r.i,'detail')}<p class="institution">${esc(r.i.name)}</p><h2 id="detail-title">${esc(programmeName(r.p,lang))}</h2><p class="detail-intro">${esc(r.p.description)}</p><div class="detail-meta"><span>After Grade ${r.entryAfter}</span><span>${esc(r.p.duration)}</span></div>${routes.filter(x=>x.programmeId===r.programmeId&&x.entryAfter===r.entryAfter).length>1?`<label class="route-picker">Admission option<select id="detail-route">${routes.filter(x=>x.programmeId===r.programmeId&&x.entryAfter===r.entryAfter).map(x=>`<option value="${x.id}" ${x.id===r.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select></label>`:''}<section><h3>${t('curriculum')}</h3><p class="full-programme-title"><b>Full programme title:</b> ${esc(r.p.name)}</p><p>${esc(r.p.languages.join(', '))}</p><p>${esc(r.p.qualification)} · ${esc(r.p.duration)} · ${esc(r.p.credits)}</p><p>${esc(r.p.campus)}</p><p>${esc(r.p.curriculum)}</p><p><b>Practical experience:</b> ${esc(r.p.practical)}</p></section><section><h3>${t('eligibility')}</h3><p><b>Admission option:</b> ${esc(r.name)} · ${esc(r.pathway)}</p><p><b>Applicant:</b> ${esc(r.applicant)}</p><p>${esc(r.eligibility)}</p><p><b>School subjects:</b> ${esc(r.subjects)}</p><p><b>Diploma recognition:</b> ${esc(r.recognition)}</p>${r.prerequisiteRouteIds?.length?`<div class="notice"><b>Regular-offer prerequisite · one available academic route</b>${r.prerequisiteRouteIds.map(id=>btn('detail',`${esc(routes.find(x=>x.id===id)?.name)} →`,'text-btn',`data-id="${id}"`)).join('')}</div>`:''}</section><section><h3>${t('exams')}</h3>${testsHtml(r)}<p class="context-note">Missing or unknown requirements need verification. Published minimum scores only establish eligibility to be considered.</p></section><section><h3>${t('cost')}</h3><h4>${esc(money(r.tuition,lang))}</h4><p>${esc(r.tuition.note)}</p><p><b>${t('fees')}:</b> ${esc(r.mandatoryFees)}</p><p><b>${t('living')}:</b> ${esc(r.living)}</p><p class="context-note">Native currencies are kept separate; no KZT conversion or net-cost estimate is implied.</p></section><section><h3>${t('funding')}</h3>${awardsHtml(r)}</section><section><h3>${t('calendar')} · planned entry ${year}</h3>${r.deadlines.length?r.deadlines.map(deadlineHtml).join(''):'No sourced deadline record. Confirm the selected intake directly.'}${!r.deadlines.some(x=>String(x.cycle).startsWith(String(year))&&x.status!=='historical')?`<div class="notice">${year} cycle dates await confirmation.</div>`:''}</section>${r.questions?.length?`<section><h3>${t('questions')}</h3><ul>${r.questions.map(q=>`<li>${esc(q)}</li>`).join('')}</ul></section>`:''}<div class="next-detail"><span>↗</span><div><strong>${t('next')}</strong><p>${esc(r.nextAction)}</p></div></div><section><h3>${t('source')}</h3>${sourceList([...(r.p.sourceIds||[]),...r.sourceIds])}</section><section><h3>Suggest a source correction</h3><p>Copy this note for the school’s designated reviewer. No submission destination has been configured.</p><label>Correction or question<textarea id="correction" rows="3" placeholder="Which fact should a reviewer check? Add an official source if you have one."></textarea></label>${btn('correction',t('copy'),'secondary',`data-id="${r.id}"`)}</section><div class="detail-actions">${btn('save',saved.includes(r.id)?t('saved'):t('save'),'primary',`data-id="${r.id}"`)}${btn('compare',`${compare.includes(r.id)?'✓ ':''}${t('compare')}`,'secondary',`data-id="${r.id}"`)}</div></div>`;simplifyDetail();localize($('#detail'));if(!$('#detail').open)$('#detail').showModal();$('#detail').scrollTop=0;}
function simplifyDetail(){const body=$('#detail .detail-body');const groups=new Map();for(const section of [...body.querySelectorAll(':scope > section')]){const heading=section.querySelector('h3');if(!heading)continue;const title=heading.textContent;let group=title===t('curriculum')?'About the programme':[t('eligibility'),t('exams'),t('questions')].includes(title)?'How to apply':[t('cost'),t('funding')].includes(title)?'Costs and scholarships':title.startsWith(t('calendar'))?'Deadlines':'Official sources';if(!groups.has(group)){const details=document.createElement('details');details.className='detail-section';const summary=document.createElement('summary');summary.textContent=group;details.append(summary);section.before(details);groups.set(group,details);}const subtitle=document.createElement('h4');subtitle.textContent=title;heading.replaceWith(subtitle);groups.get(group).append(section);}const next=body.querySelector('.next-detail');if(next)groups.get('How to apply')?.append(next);for(const note of body.querySelectorAll('.context-note'))note.remove();}
function comparePage(){const rs=compare.map(id=>routes.find(r=>r.id===id));return `<div class="page-body compare-page">${pageTitle('compare',t('limit'))}${rs.length?`<div class="comparison-toolbar"><label>${t('year')}<input type="number" id="year" min="2026" max="2040" value="${year}"></label>${btn('clearCompare',t('clear'),'text-btn')}</div><section class="comparison-grid" style="--compare-count:${rs.length}" aria-label="Programme route comparison">${rs.map(r=>{const next=nearestDeadline(r,year);const multiple=routes.filter(x=>x.programmeId===r.programmeId&&x.entryAfter===r.entryAfter).length>1;return `<article class="comparison-card" data-comparison-id="${r.id}"><div class="comparison-header">${campusImage(r.i,'comparison')}<div class="comparison-heading"><p class="institution">${esc(r.i.name)}</p>${btn('compare','×','comparison-remove',`data-id="${r.id}" aria-label="${t('remove')} ${esc(programmeName(r.p,lang))} ${esc(r.name)}"`)}</div><h2>${esc(programmeName(r.p,lang))}</h2><p class="comparison-location">${esc(r.i.country)} · After Grade ${r.entryAfter} · ${esc(r.p.duration)}</p>${multiple?`<p class="comparison-route">${esc(r.name)}</p>`:''}</div><dl class="comparison-facts"><div data-fact="cost"><dt>Tuition reference</dt><dd>${esc(money(r.tuition,lang))}</dd></div><div data-fact="funding"><dt>Scholarship options</dt><dd>${r.awards.length?[...new Set(r.awards.map(a=>coverageLabels[a.coverage]))].map(label=>`<span>${esc(label)}</span>`).join(''):'Scholarships to confirm'}</dd></div><div data-fact="tests"><dt>${t('exams')}</dt><dd><ul class="comparison-tests">${comparisonTests(r).map(item=>`<li class="${item.status}">${esc(item.label)}${item.english?'':`<small>${esc(testLabels[item.status])}</small>`}</li>`).join('')}</ul></dd></div><div data-fact="deadline"><dt>Next confirmed deadline</dt><dd>${next?`<time datetime="${next.date}">${esc(new Intl.DateTimeFormat(lang,{day:'numeric',month:'short',year:'numeric',timeZone:'UTC'}).format(new Date(next.date+'T12:00:00Z')))}</time><small>${esc(next.type)}</small>`:'No upcoming confirmed date'}</dd></div></dl><div class="comparison-action">${btn('detail','Details','primary',`data-id="${r.id}"`)}</div></article>`;}).join('')}</section><p class="comparison-note">Prices and scholarships are references. Check the intake and conditions in Details.</p>`:`<div class="empty"><h2>Nothing to compare yet</h2><p>Add options from the catalogue.</p>${btn('page',t('explore'),'primary','data-page="explore"')}</div>`}</div>`;}
function latestCheck(){return d.meta?.checked||d.sources.map(s=>s.checked).sort().at(-1);}
function latestCycle(sources){return sources.filter(s=>s.status==='verified').map(s=>s.cycle).filter(c=>/20\d{2}/.test(c)).sort((a,b)=>Math.max(...(b.match(/20\d{2}/g)||[0]).map(Number))-Math.max(...(a.match(/20\d{2}/g)||[0]).map(Number)))[0]||'Undated — cycle confirmation needed';}
function referenceCredits(){return `<details class="all-sources"><summary>Country and subject lists</summary><p>Country and territory list: ISO 3166-1. Subject names adapted and translated from UNESCO-UIS ISCED-F 2013 (2015).</p><p><a href="https://www.iso.org/iso-3166-country-codes.html" target="_blank" rel="noopener noreferrer">ISO 3166-1 ↗</a> · <a href="https://www.uis.unesco.org/sites/default/files/medias/fichiers/2025/04/international-standard-classification-of-education-fields-of-education-and-training-2013-detailed-field-descriptions-2015-en.pdf" target="_blank" rel="noopener noreferrer">UNESCO-UIS ISCED-F 2013 ↗</a> · <a href="https://creativecommons.org/licenses/by-sa/3.0/igo/" target="_blank" rel="noopener noreferrer">CC BY-SA 3.0 IGO ↗</a></p></details>`;}
function coveragePage(){return `<div class="page-body narrow">${pageTitle('coverage','A simple way to explore your next step.')}<div class="about-intro"><p>Search, save a few options and compare them.</p><p class="subtle">The catalogue is growing. Check the official requirements before applying.</p></div><div class="coverage-summary"><div><strong>${d.institutions.length}</strong><span>institutions</span></div><div><strong>${d.programmes.length}</strong><span>programmes</span></div><div><strong>${esc(new Intl.DateTimeFormat(lang,{day:'numeric',month:'short',year:'numeric',timeZone:'UTC'}).format(new Date(latestCheck()+'T12:00:00Z')))}</strong><span>latest research check</span></div></div><details class="about-section"><summary>Where you can study</summary><div class="coverage-grid">${regions.map(region=>{const rs=routes.filter(r=>r.i.region===region);const sources=[...new Set(rs.flatMap(r=>r.sourceIds))].map(id=>d.sources.find(s=>s.id===id)).filter(Boolean);return `<article><h3>${region}</h3><p>${rs.length} routes · ${new Set(rs.map(r=>r.p.id)).size} programmes</p><small>${rs.length?`Latest verified cycle: ${esc(latestCycle(sources))}`:'Insufficient verified data. Region supported for future entries.'}</small>${btn('region',`Explore ${region} ↗`,'text-btn',`data-region="${region}"`)}</article>`;}).join('')}</div></details><details class="about-section"><summary>How to read this catalogue</summary><div class="editorial"><h3>Sources keep their own dates</h3><p>Your planned entry year changes the deadline context. It does not turn an older fee schedule or grant call into a new one.</p><h3>Unknown is a useful answer</h3><p>Unknown tests, diploma equivalence, costs and progression conditions need a check with the institution. They are never confirmed exemptions.</p><h3>Funding means different things</h3><p>A full scholarship includes tuition and a maintenance or housing package. Tuition-only, partial and conditional aid have separate labels.</p></div></details><details class="about-section"><summary>Data & privacy</summary><p>Interface language, planned entry year, bookmarks and comparison choices stay in this browser.</p><p>No names, marks, birthdates or contacts are collected. Clearing browser storage removes local choices. Official source links open the institution’s website.</p>${btn('clearStorage','Clear my local preferences and bookmarks','text-btn')}</details><details class="about-section"><summary>Review and corrections</summary><p>A teacher or counsellor should own annual data review. Open a route to copy a correction. The school has not supplied an authorised submission address.</p>${btn('copyCoverage','Copy catalogue review note','secondary')}<details class="all-sources"><summary>Questions awaiting verification</summary>${routes.filter(r=>r.questions?.length).map(r=>`<p><strong>${esc(r.i.name)} · ${esc(programmeName(r.p,lang))}</strong><br>${esc(r.questions.join(' '))}</p>`).join('')}</details></details><details class="about-section"><summary>All official source records (${d.sources.length})</summary>${sourceList(d.sources.map(s=>s.id))}</details>${photoCredits()}${referenceCredits()}</div>`;}
function tray(){if(page==='compare'){$('#tray').innerHTML='';return;}const rs=compare.map(id=>routes.find(r=>r.id===id));$('#tray').innerHTML=rs.length?`<div class="compare-tray"><span><b>${rs.length} / 3</b> ${t('compare')}<small>${rs.map(r=>esc(programmeName(r.p,lang))).join(' · ')}</small></span><div>${btn('clearCompare',t('clear'),'text-btn')}${btn('page',`${t('compare')} →`,'primary','data-page="compare"')}</div></div>`:'';}
function render({focus=false}={}){header();$('#main').innerHTML=page==='explore'?explorer():page==='shortlist'?shortlistPage():page==='compare'?comparePage():page==='calendar'?calendarPage():coveragePage();$('#main').insertAdjacentHTML('beforeend',`<footer class="simple-footer">${btn('page',t('calendar'),'text-btn','data-page="calendar"')}${btn('page','About','text-btn','data-page="coverage"')}</footer>`);if(page==='explore')renderResults();tray();localize();if(focus){window.scrollTo({top:0});$('#main').focus({preventScroll:true});}}
function go(p){page=p;render({focus:true});}
async function copy(text){try{await navigator.clipboard.writeText(text);toast('Copied. Share it with the designated school reviewer.');}catch{const ta=document.createElement('textarea');ta.value=text;ta.setAttribute('readonly','');$('#detail').open?$('#detail').append(ta):document.body.append(ta);ta.select();const ok=document.execCommand('copy');ta.remove();toast(ok?'Copied.':'Copy is unavailable in this browser. Select the note from the source details.');}}
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el)return;const action=el.dataset.action,id=el.dataset.id;e.preventDefault();if(action==='page'||action==='home'){go(el.dataset.page||'explore');}else if(action==='entry'){visibleLimit=6;f.stage=el.dataset.stage;render();$('#catalogue').scrollIntoView({block:'start'});}else if(action==='reset'){visibleLimit=6;f={fields:[],year,costUnknown:true,testUnknown:false};render();$('#catalogue')?.scrollIntoView({block:'start'});}else if(action==='unt'){f={fields:[],year,costUnknown:true,testUnknown:false,stage:'11',region:'Kazakhstan',test:'UNT',testRole:'required'};go('explore');$('#catalogue').scrollIntoView();}else if(action==='after11'){f.stage='11';render();$('#catalogue').scrollIntoView();}else if(action==='region'){visibleLimit=6;f={fields:[],year,costUnknown:true,testUnknown:false,region:el.dataset.region};go('explore');$('#catalogue').scrollIntoView();}else if(action==='save'){saved=saved.includes(id)?saved.filter(x=>x!==id):[...saved,id];storeList();const open=$('#detail').open;const y=scrollY;render();window.scrollTo(0,y);if(open)openDetail(id);}else if(action==='compare'){if(!compare.includes(id)&&compare.length===3){toast(t('limit'));return;}compare=addComparison(compare,id);storeList();const open=$('#detail').open;const y=scrollY;render();window.scrollTo(0,y);if(open)openDetail(id);}else if(action==='clearCompare'){compare=[];storeList();render();}else if(action==='more'){const next=filterRoutes(routes,{...f,year})[visibleLimit];visibleLimit+=6;renderResults();if(next)$(`#results [data-action="detail"][data-id="${next.id}"]`)?.focus();}else if(action==='detail'){openDetail(id);}else if(action==='close'){$('#detail').close();selected=null;}else if(action==='correction'){const r=routes.find(r=>r.id===id);copy(`${tr('Divergents source review')}\n${tr('Route:')} ${r.id} · ${tr(r.i.name)} · ${tr(r.p.name)}\n${tr('Route cycle:')} ${tr(r.cycle)}; ${tr('planned entry:')} ${year}\n${tr('Question:')} ${$('#correction').value||tr('[add correction]')}\n${tr('Sources:')}\n${[...new Set([...r.p.sourceIds,...r.sourceIds])].map(id=>d.sources.find(s=>s.id===id)?.url).join('\n')}`);}else if(action==='copyCoverage'){copy(tr(`Divergents catalogue review · ${latestCheck()}\n${routes.length} routes; ${d.programmes.length} programmes.\nPlease review outstanding questions, current cycles and official source links before school rollout.`));}else if(action==='clearStorage'){saved=[];compare=[];year=2027;f={fields:[],year,costUnknown:true};storeList();persist();render();toast('Local choices cleared.');}});
document.addEventListener('input',e=>{if(e.target.id==='search'){f.q=e.target.value;renderResults({reset:true});}else if(e.target.dataset.filter&&e.target.type!=='checkbox'&&e.target.tagName!=='SELECT'){f[e.target.dataset.filter]=e.target.value;renderResults();}});
document.addEventListener('change',e=>{if(e.target.id==='detail-route'){openDetail(e.target.value);$('#detail-route')?.focus();}else if(e.target.id==='lang'){lang=e.target.value;persist();$('#toast').textContent='';render();}else if(e.target.id==='year'){year=+e.target.value||2027;f.year=year;persist();render();}else if(e.target.id==='onlySaved'){onlySaved=e.target.checked;render();}else if(e.target.dataset.field){const field=e.target.dataset.field;f.fields=e.target.checked?[...new Set([...f.fields,field])]:f.fields.filter(x=>x!==field);const y=scrollY;render();window.scrollTo(0,y);}else if(e.target.dataset.filter){const key=e.target.dataset.filter;f[key]=e.target.type==='checkbox'?e.target.checked:e.target.value;if(key==='region')f.country='';if(key==='country')delete f.region;if(['region','currency'].includes(key)){const y=scrollY;render();window.scrollTo(0,y);}else if(key==='stage')render();else if(key==='subject'){delete f.subject;f.fields=e.target.value?[e.target.value]:[];renderResults({reset:true});}else renderResults({reset:true});}});
$('#detail').addEventListener('click',e=>{if(e.target===$('#detail'))$('#detail').close();});
document.addEventListener('error',e=>{if(e.target.tagName==='IMG'&&e.target.dataset.campusPhoto){const figure=e.target.closest('.campus-photo');e.target.hidden=true;figure?.classList.add('photo-unavailable');const fallback=figure?.querySelector('.photo-fallback');if(fallback)fallback.hidden=false;}},true);
render();
